def bucket_4(values, width=11):
    """Return a dict mapping floor-divided bucket indices to counts."""
    if width <= 0:
        raise ValueError("width must be positive")
    counts = {}
    for v in values:
        idx = v // width
        counts[idx] = counts.get(idx, 0) + 1
    return counts

